assert len(packet) == 122
rows = []
for item, (d, c, t, reason) in zip(packet, SCORES):
    total = d + c + t
    rows.append({"anon_id": item["anon_id"], "direction": d, "claims": c, "timing": t,
                 "total": total, "pass": total >= 4, "reason": reason})
assert len(rows) == 122
assert {r["anon_id"] for r in rows} == {p["anon_id"] for p in packet}
for r in rows:
    assert r["total"] == r["direction"] + r["claims"] + r["timing"]
    assert r["pass"] == (r["total"] >= 4)
out = BASE/"judging"/"judgeX-block1.jsonl"
out.write_text("\n".join(json.dumps(r, ensure_ascii=False) for r in rows) + "\n")
print("written", len(rows), "pass", sum(1 for r in rows if r["pass"]))
